\begin{theorem}[Almost sure global convergence]
\label{thm:global}
Suppose that \eqref{eq:opt} is variationally coherent.
Then, under \cref{asm:diff,asm:L2,asm:reciprocity}, $\act_{\run}$ converges with probability $1$ to a \textpar{possibly random} minimum point of \eqref{eq:opt}.
\end{theorem}

