\begin{theorem}[Almost sure global convergence]
\label{thm:global}
Suppose that \eqref{eq:opt} is variationally coherent.
Then, under \cref{asm:diff,asm:L2,asm:reciprocity}, $\act_{\run}$ converges with probability $1$ to a \textpar{possibly random} minimum point of \eqref{eq:opt}.
\end{theorem}

\begin{proof}[Proof of \cref{thm:global}]
Let $\sol\in\sols$ be a minimum point of \eqref{eq:opt}.
Then, letting $\fench_{\run} = \fench(\sol,\score_{\run})$, \cref{lem:Fenchel} gives
\begin{flalign}
\label{eq:Fench-bound1}
\fench_{\run+1}
	= \fench(\sol,\score_{\run+1})
	&= \fench(\sol,\score_{\run} + \step_{\run}\est\payv_{\run})
	\notag\\
	&\leq \fench(\sol,\score_{\run})
	+ \step_{\run} \braket{\est\payv_{\run}}{\act_{\run} - \sol}
	+ \frac{\step_{\run}^{2}}{2\strong} \dnorm{\est\payv_{\run}}^{2}
	\notag\\
	&= \fench_{\run}
	+ \step_{\run} \braket{\payv(\act_{\run})}{\act_{\run} - \sol}
	+ \step_{\run} \snoise_{\run}
%	+ \step_{\run} \braket{\noise_{\run}}{\act_{\run} - \sol}
	+ \frac{\step_{\run}^{2}}{2\strong} \dnorm{\est\payv_{\run}}^{2}
	\notag\\
	&\leq \fench_{\run}
	+ \step_{\run} \snoise_{\run}
	+ \frac{\step_{\run}^{2}}{2\strong} \dnorm{\est\payv_{\run}}^{2},
\end{flalign}
where we set $\snoise_{\run} = \braket{\noise_{\run}}{\act_{\run} - \sol}$ in the third line and used the fact that $\obj$ satisfies \eqref{eq:VC} in the last one.
Since $\score_{\run}$ is predictable relative to $\filter_{\run}$ (\ie $\score_{\run}$ is $\filter_{\run-1}$-measurable), the process $\fench_{\run} = \fench(\sol,\score_{\run})$ is itself adapted to the shifted filtration $\alt\filter_{\run} = \sigma(\sample_{\start},\score_{2}\dotsc,\sample_{\run-1},\score_{\run}) = \filter_{\run-1}$.
Thus, taking conditional expectations and invoking \cref{asm:L2}, the bound \eqref{eq:Fench-bound1} becomes:
\begin{flalign}
\label{eq:Fench-bound-cond}
\exof{\fench_{\run+1} \given \alt\filter_{\run}}
	&\leq \fench_{\run}
	+ \exof{\snoise_{\run} \given \alt\filter_{\run}}
	+ \frac{\step_{\run}^{2}}{2\strong} \exof{\dnorm{\est\payv_{\run}}^{2} \given \alt\filter_{\run}}
	\notag\\
	&= \fench_{\run}
	+ \exof{\snoise_{\run} \given \filter_{\run-1}}
	+ \frac{\step_{\run}^{2}}{2\strong} \exof{\dnorm{\nabla\sobj(\act_{\run};\sample_{\run})}^{2} \given \filter_{\run-1}}
	\notag\\
	&\leq \fench_{\run}
	+ \frac{\step_{\run}^{2} \vbound^{2}}{2\strong},
\end{flalign}
where, in the last line, we used \cref{asm:L2} and the fact that $\noise_{\run}$ is a \acl{MDS} (so $\exof{\snoise_{\run} \given \filter_{\run-1}} = 0$; for a detailed derivation, see the proof of \cref{prop:recurrence} in \cref{app:proofs}).
Hence, with $\sum_{\run=\start}^{\infty} \step_{\run}^{2} < \infty$, \cref{lem:Gladyshev} implies that $\fench_{\run}$ converges \as to some finite limit $\fench_{\infty}$.

Now, by \cref{prop:recurrence}, there exists \as a subsequence $\score_{\run_{\runalt}}$ of $\score_{\run}$ and some (possibly random) $\sol\in\sols$ such that $\lim_{\runalt\to\infty} \fench(\sol,\score_{\run_{\runalt}}) = 0$.
Since the limit $\lim_{\run\to\infty} \fench(\sol,\score_{\run})$ exists \as, it follows that $\lim_{\run\to\infty} \fench(\sol,\score_{\run}) = 0$.
This shows that, with probability $1$, $\act_{\run} = \mirror(\score_{\run})$ converges to some (random) minimum point $\sol$ of \eqref{eq:opt}, as claimed.
\end{proof}

Let $\states$ be a convex compact subset of a $\vdim$-di\-men\-sio\-nal vector space $\vecspace$ with norm $\norm{\argdot}$.
%and let $\sample$ be a random variable on an underlying (complete) probability space $\pspace$
Throughout this paper, we will focus on stochastic optimization problems of the general form
\begin{equation}
\label{eq:opt}
\tag{Opt}
\begin{aligned}
\text{minimize}
&\quad
\obj(\state),
\\
\text{subject to}
&\quad
\state\in\states,
\end{aligned}
\end{equation}
%where the objective function $\obj\from\states\to\R$ is of the form
where
\begin{equation}
\label{eq:obj}
\obj(\state)
	= \exof{\sobj(\state;\sample)}
\end{equation}
for some stochastic objective function $\sobj\from\states\times\samples\to\R$ defined on an underlying (complete) probability space $\pspace$.

\begin{assumption}
\label{asm:diff}
$\sobj(\state, \sample)$ is continuously differentiable in $\state$ for almost all $\sample\in\samples$.
\end{assumption}

\begin{assumption}
\label{asm:L2}
The gradient of $\sobj$ is uniformly bounded in $L^{2}$, \ie $\exof{\dnorm{\nabla\sobj(\state;\sample)}^{2}} \leq \vbound^{2}$ for some finite $\vbound\geq0$ and all $\state\in\states$.
\end{assumption}

\begin{remark*}
In the above, gradients are treated as elements of the dual space $\dstates\equiv\dual\vecspace$ of $\vecspace$, and $\dnorm{\dstate} = \sup\setdef{\braket{\dstate}{\state}}{\norm{\state}\leq1}$ denotes the dual norm of $\dstate\in\dstates$.
We also note that $\nabla\sobj(\state;\sample)$ refers to the gradient of $\sobj(\state;\sample)$ with respect to $\state$;
since $\samples$ is not assumed to carry a differential structure, there is no danger of confusion.
\end{remark*}

\cref{asm:L2} is also standard in the stochastic optimization literature:
it holds trivially if $\sobj$ is uniformly Lipschitz (another commonly used condition) and, by the dominated convergence theorem, it further implies that $\obj$ is smooth and $\nabla\obj(\state) = \nabla\exof{\sobj(\state;\sample)} = \exof{\nabla\sobj(\state;\sample)}$ is bounded.
As a result, the solution set
\begin{equation}
\label{eq:solset}
\sols
	= \argmin\obj
\end{equation}
of \eqref{eq:opt} is closed and nonempty (by the compactness of $\states$ and the continuity of $\obj$).

\begin{definition}
\label{def:VC}
We say that \eqref{eq:opt} is \emph{variationally coherent} if
\begin{equation}
\label{eq:VC}
\tag{VC}
\braket{\nabla\obj(\state)}{\state - \sol}
	\geq 0
	\quad
	\text{for all $\state\in\states$, $\sol\in\sols$},
\end{equation}
and there exists some $\sol\in\sols$ such that equality holds in \eqref{eq:VC} only if $\state \in \sols$.
\end{definition}

The main idea of the method is as follows:
At each iteration, the algorithm takes as input an \ac{iid} sample of the gradient of $\sobj$ at the algorithm's current state.
Subsequently, the method takes a step along this stochastic gradient in the dual space $\dstates\equiv\dspace$ of $\vecspace$ (where gradients live), the result is ``mirrored'' back to the problem's feasible region $\states$, and the process repeats.
Formally, this gives rise to the recursion
\begin{equation}
\label{eq:SMD}
\tag{SMD}
\begin{aligned}
\act_{\run}
	&= \mirror(\score_{\run})
	\\
\score_{\run+1}
	&= \score_{\run} - \step_{\run} \nabla\sobj(\act_{\run};\sample_{\run})
\end{aligned}
\end{equation}
where:
\begin{enumerate}
\item
$\run=\running$ denotes the algorithm's running counter.
\item
$\score_{\run}\in\dstates$ is a score variable that aggregates gradient steps up to stage $\run$.
\item
$\mirror\from\dstates\to\states$ is the \emph{mirror map} that outputs a solution candidate $\act_{\run}\in\states$ as a function of the score variable $\score_{\run}\in\dspace$.
\item
$\sample_{\run}\in\samples$ is a sequence of \ac{iid} samples.%
\footnote{The indexing convention for $\sample_{\run}$ means that $\score_{\run}$ and $\act_{\run}$ are \emph{predictable} relative to the natural filtration $\filter_{\run} = \sigma(\sample_{1},\dotsc,\sample_{\run})$ of $\sample_{\run}$, \ie $\score_{\run+1}$ and $\act_{\run+1}$ are both $\filter_{\run}$-measurable.
To this history, we also attach the trivial $\sigma$-algebra as $\filter_{0}$ for completeness.}
\item
$\step_{\run}>0$ is the algorithm's step-size sequence, assumed in what follows to satisfy the Robbins\textendash Monro summability condition
\begin{equation}
\label{eq:L2L1}
\sum_{\run=1}^{\infty} \step_{\run}^{2}
	<\infty
	\quad
	\text{and}
	\quad
	\sum_{\run=1}^{\infty} \step_{\run}
	= \infty.
\end{equation}
\end{enumerate}

\begin{algorithm}[tbp]
\caption{Stochastic mirror descent (\ac{SMD})}
\label{alg:SMD}
%----------------------------------------------------------------------
%%% SMD ALGORITHM
%----------------------------------------------------------------------
% !TEX root = ../Main.tex


\tt
\begin{algorithmic}[1]
\Require
	mirror map $\mirror\from\dstates\to\states$;
	step-size sequence $\step_{\run}>0$
\State
	choose $\score\in\dstates \equiv \dspace$
	\Comment{initialization}
\For{$\run=\running$}
%	\State $\act_{\run} = \mirror(\score_{\run-1})$
%	\State $\score_{\run} = \score_{\run-1} - \step_{\run} \nabla\sobj(\act_{\run},\sample_{\run})$
%	at each stage $\run=\running$
	\State
		set $\act \leftarrow \mirror(\score)$
		\Comment{set state}
	\State
		draw $\sample\in\samples$
		\Comment{gradient sample}
	\State
		get $\est\payv = -\nabla\sobj(\act;\sample)$
		\Comment{get oracle feedback}
	\State
		set $\score \leftarrow \score + \step_{\run} \est\payv$
		\Comment{update score variable}
\EndFor
\\
\Return $\act$
	\Comment{output}
\end{algorithmic}
\end{algorithm}

In more detail, the algorithm's mirror map $\mirror\from\dstates\to\states$ is defined as
\begin{equation}
\label{eq:mirror}
\mirror(\dstate)
	= \argmax_{\state\in\states} \{\braket{\dstate}{\state} - \hreg(\state)\},
\end{equation}
where the \emph{regularizer} (or \emph{penalty function}) $\hreg\from\states\to\R$ is assumed to be continuous and strongly convex on $\states$, \ie there exists some $\strong>0$ such that
\begin{equation}
\label{eq:strong}
\hreg(\tau\state + (1-\tau)\alt\state)
	\leq \tau \hreg(\state) + (1-\tau) \hreg(\alt\state) - \tfrac{1}{2} \strong\tau(1-\tau) \norm{\alt\state - \state}^{2},
\end{equation}
for all $\state,\alt\state\in\states$ and all $\tau\in[0,1]$.
The mapping $\mirror\from\dspace\to\states$ defined by \eqref{eq:mirror} is then called the \emph{mirror map induced by $\hreg$}.

\begin{definition}
\label{def:Fenchel}
Let $h\from\states \to \R$ be a regularizer on $\states$.
The induced \emph{Fenchel coupling} $\fench(\base,\dstate)$ between a base-point $\base\in\states$ and a dual vector $\dstate\in\dstates$ is defined as
\begin{equation}
\label{eq:Fenchel}
\fench(\base,\dstate)
	= \hreg(\base) + \hreg^{\ast}(\dstate) - \braket{\dstate}{\base}
\end{equation}
where $\hreg^{\ast}(\dstate) = \max_{\state\in\states} \{ \braket{\dstate}{\state} - \hreg(\state) \}$ denotes the convex conjugate of $h$.
\end{definition}

\begin{assumption}
\label{asm:reciprocity}
$\fench(\base,\dstate_{\run}) \to 0$ whenever $\mirror(\dstate_{\run})\to\base$.
\end{assumption}

\begin{definition}
\label{def:metrics}
%Let $h$ be a regularizer on $\states$ and
Let $\region$ be a subset of $\states$.
\begin{subequations}
\begin{enumerate}
\item
The \emph{distance} between $\region$ and $\state\in\states$ is defined as $\dist(\region,\state) = \inf_{\alt\state\in\region} \norm{\alt\state - \state}$,
and the corresponding \emph{$\eps$-neighborhood of $\region$} is
\begin{alignat}{2}
\label{eq:ball-norm}
\ball(\region,\eps)
	&= \setdef{\state\in\states}{\dist(\region,\state) < \eps}.
\intertext{%
\item
The (setwise) \emph{Fenchel coupling} between $\region$ and $\dstate\in\dstates$ is defined as $\fench(\region,\dstate) = \inf_{\state\in\region} \fench(\state,\dstate)$,
and the corresponding \emph{Fenchel $\delta$-zone} of $\region$ under $h$ is}
\label{eq:ball-Fench}
\fball(\region,\delta)
	&= \setdef{\state\in\states}{\text{$\state=\mirror(\dstate)$ for some $\dstate\in\dstates$ with $\fench(\region,\dstate) < \delta$}}.
\end{alignat}
\end{enumerate}
\end{subequations}
\end{definition}

\begin{lemma}
\label{lem:Fenchel}
Let $h$ be a $\strong$-strongly convex regularizer on $\states$.
Then, for all $\base\in\states$ and all $\dstate,\alt\dstate\in\dstates$, we have:
\begin{subequations}
\label{eq:Fench-properties}
\begin{alignat}{2}
\label{eq:Fench-norm}
&a)
	\;\;
	\fench(\base,\dstate)
	&&\geq \frac{\strong}{2} \, \norm{\mirror(\dstate) - \base}^{2}.
	\hspace{17em}
	\\[3pt]
\label{eq:Fench-bound}
&b)
	\;\;
	\fench(\base,\alt\dstate)
	&&\leq \fench(\base,\dstate) + \braket{\alt\dstate - \dstate}{\mirror(\dstate) - \base} + \frac{1}{2\strong} \dnorm{\alt\dstate - \dstate}^{2}.
\end{alignat}
\end{subequations}
%\begin{enumerate}
%\item
%$\fench(\base, \dstate) \geq \frac{1}{2} \strong\norm{\mirror(\dstate) - \base}^{2}, \forall x \in \states, \forall y \in \R^{n}.$
%\item 
%$\fench(\state, \tilde{\dstate}) \le \fench(\state, \dstate) + \braket{\tilde{\dstate} - y}{\mirror(\dstate) - x} + \frac{1}{2\strong} \|\tilde{\dstate} - y \|_*^2, \forall x \in \states, \forall \tilde{\dstate}, y \in \R^{n}.$
%\end{enumerate}
\end{lemma}

\begin{proposition}
\label{prop:recurrence}
Fix some $\eps>0$ and $\delta>0$.
If \eqref{eq:opt} is variationally coherent and \cref{asm:diff,asm:L2,asm:reciprocity} hold, the \textpar{random} iterates $\act_{\run}$ of \cref{alg:SMD} enter $\ball(\sols,\eps)$ and $\fball(\sols,\delta)$ infinitely many times \as.
\end{proposition}

\begin{corollary}
\label{cor:recurrence}
With probability $1$, there exists a subsequence $\act_{\run_{\runalt}}$ of $\act_{\run}$ converging to a \textpar{random} minimum point $\sol$ of \eqref{eq:opt}.
\end{corollary}

\begin{proofstep}{Martingale properties of $\score_{\run}$}
First, let
\begin{equation}
\payv(\state)
	= - \exof{\nabla\sobj(\state;\sample)} = -\nabla\obj(\state)
\end{equation}
denote the negative gradient of $\obj$ at $\state\in\states$, and write
\begin{equation}
\label{eq:oracle}
\est\payv_{\run}
	= -\nabla\sobj(\act_{\run};\sample_{\run})
\end{equation}
for the corresponding oracle feedback at stage $\run$.
Then, \cref{alg:SMD} may be written in Robbins\textendash Monro form as
\begin{equation}
\label{eq:SA}
\score_{\run+1}
	= \score_{\run} + \step_{\run} \est\payv_{\run}
	= \score_{\run} + \step_{\run} \bracks{\payv(\act_{\run}) + \noise_{\run}},
\end{equation}
where
\begin{equation}
\noise_{\run}
	= \nabla\obj(\act_{\run}) - \nabla\sobj(\act_{\run};\sample_{\run})
\end{equation}
denotes the difference between the mean gradient of $\obj$ at $\act_{\run}$ and the $\run$-th stage gradient sample.%
\footnote{Recall here that there is a one-step offset between $\act_{\run}$ and $\sample_{\run+1}$ at the $\run$-th iteration of \ac{SMD}.}
\begin{subequations}
\label{eq:MDS}
By construction, $\noise_{\run}$ is a \acl{MDS} relative to the history (natural filtration) $\filter_{\run} = \sigma(\sample_{1},\dotsc,\sample_{\run})$ of $\sample_{\run}$, \ie
\begin{equation}
\label{eq:zero-mean}
\exof{\noise_{\run}\given\filter_{\run-1}}
	= 0
	\quad
	\text{for all $\run$.}
\end{equation}
Furthermore, by \cref{asm:L2}, it readily follows that $\noise_{\run}$ has uniformly bounded second moments, \ie there exists some finite $\noisedev\geq0$ such that
\begin{equation}
\label{eq:MSE}
\exof{\dnorm{\noise_{\run}}^{2} \given \filter_{\run-1}}
	\leq \noisevar
	\quad
	\text{for all $\run$},
\end{equation}
implying in turn that $\noise_{\run}$ is bounded in $L^{2}$ (for a more detailed treatment, see \cref{app:proofs}).
\end{subequations}
\end{proofstep}

\begin{proofstep}{Recurrence of $\eps$-neighborhoods}
Invoking the \acl{LLN} for $L^{2}$-bounded \aclp{MDS} and using the Fenchel coupling as an energy function (cf.~\cref{app:proofs}), we show that if $\act_{\run}$ remains outside $\ball(\sols,\eps)$ for sufficiently large $\run$, we must also have $\fench(\sols,\score_{\run})\to-\infty$ \as.
This contradicts the positive-definiteness of $\fench$, so $\act_{\run}$ must enter $\ball(\sols,\eps)$ infinitely often \as.
\end{proofstep}

\begin{proofstep}{Recurrence of Fenchel zones}
By reciprocity (\cref{asm:reciprocity}), $\fball(\sols, \delta)$ always contains an $\eps$-neighborhood of $\sols$.
%within it: $\forall \delta > 0$, $\exists \eps(\delta) > 0$ such that: $\ball(\sols,\eps) \subset \fball(\sols, \delta)$.
Since $\act_{\run}$ enters $\ball(\sols,\eps)$ infinitely many times \as, the same must hold for $\fball(\sols, \delta)$.
Our claim and \cref{cor:recurrence} then follow immediately.
\end{proofstep}

\begin{proofof}{Proof of \cref{lem:Fenchel}}
To prove the first claim, let $\state =\mirror(\dstate) = \argmax_{\alt\state\in\states}\{\braket{\dstate}{\alt\state} - \hreg(\alt\state)\}$, so $\dstate\in\pd \hreg(\state)$ from standard results in convex analysis \cite{Roc70}.
%($y$ is a subgradient of $\hreg(p)$ if and only if $p=\mirror(\dstate)$).
We thus get:
\begin{equation}
\label{eq:Fench-sub}
\fench(\base,\dstate) = \hreg(\base) + \hreg^{\ast}(\dstate) - \braket{\dstate}{\base}
%	= \hreg(\base) + \braket{\dstate}{\mirror(\dstate)} - \hreg(\mirror(\dstate)) - \braket{\dstate}{\base}
	= \hreg(\base) - \hreg(\state) - \braket{\dstate}{\base - \state}.
\end{equation}
Since $\dstate \in \pd \hreg(\state)$ and $\hreg$ is $\strong$-strongly convex, we also have
\begin{equation}
\hreg(\state) + \tau\braket{\dstate}{\base - \state}
	\leq \hreg(\state + \tau(\base - \state))
	\leq (1-\tau) \hreg(\state) + \tau \hreg(\base) - \tfrac{1}{2} \strong \tau(1-\tau) \norm{\state - \base}^{2}
\end{equation}
for all $\tau\in[0,1]$, thereby leading to the bound
\begin{equation}
\label{eq:divbound}
\tfrac{1}{2} \strong(1-\tau) \norm{\state - \base}^{2}
	\leq \hreg(\base) - \hreg(\state) - \braket{\dstate}{\base - \state}
	= \fench(\base,\dstate).
\end{equation}
Our claim then follows by letting $\tau\to0^{+}$ in \eqref{eq:divbound}.

For our second claim, we start by citing a well-known duality principle for strongly convex functions \cite[Theorem 12.60]{RW98}:
If $f\from\R^{\vdim}\to\R\cup\{-\infty,+\infty\}$ is proper, lower semi-continuous and convex, its convex conjugate $f^{\ast}$ is $\sigma$-strongly convex if and only if $f$ is differentiable and satisfies
\begin{equation}
f(\alt\state)
	\leq f(\state) + \braket{\nabla f(\state)}{\alt\state - \state} + \frac{1}{2\sigma} \norm{\alt\state - \state}^{2}
\end{equation}
for all $\state,\alt\state\in\R^{\vdim}$.
In our case, if we extend $\hreg$ to all of $\vecspace$ by setting $\hreg\equiv+\infty$ outside $\states$, we have that $\hreg$ is $\strong$-strongly convex, lower semi-continuous and proper, so $(\hreg^{\ast})^{\ast} = \hreg$ \cite[Theorem 11.1]{RW98}.
It is also easy to see that $\hreg^{\ast}$ is proper, lower semi-continuous and convex (since it is a point-wise maximum of affine functions by definition), so the $\strong$-strong convexity of $\hreg = (\hreg^{\ast})^{\ast}$ implies that $\hreg^{\ast}$ is differentiable and satisfies
\begin{flalign}
\label{eq:smoothness}
\hreg^{\ast}(\alt\dstate)
	&\leq \hreg^{\ast}(\dstate)
	+ \braket{\alt\dstate - \dstate}{\nabla \hreg^{\ast}(\dstate)}
	+ \frac{1}{2\strong} \dnorm{\alt\dstate - \dstate}^{2}
	\\
	&= \hreg^{\ast}(\dstate)
	+ \braket{\alt\dstate - \dstate}{\mirror(\dstate)} +
	\frac{1}{2\strong} \dnorm{\alt\dstate - \dstate}^{2}
\end{flalign}
for all $\dstate,\alt\dstate\in\dstates$, where the last equality follows from the fact that $\nabla \hreg^{\ast}(\dstate) = \mirror(\dstate)$.
Therefore, substituting the preceding inequality in the definition of the Fenchel coupling, we obtain
\begin{flalign}
\fench(\state,\alt\dstate)
	&= \hreg(\state) + \hreg^{\ast}(\alt\dstate) - \braket{\alt\dstate}{\state}
	\notag\\
	&\leq \hreg(\state) + \hreg^{\ast}(\dstate) + \braket{\alt\dstate - \dstate}{\nabla \hreg^{\ast}(\dstate)} + \frac{1}{2\strong} \dnorm{\alt\dstate - \dstate}^{2} - \braket{\alt\dstate}{\state}
	\notag\\
	&= \fench(\state,\dstate) + \braket{\alt\dstate - \dstate}{\mirror(\dstate) - \state} + \frac{1}{2\strong} \dnorm{\alt\dstate - \dstate}^{2},
\end{flalign}
and our assertion follows.
\end{proofof}

\begin{proofof}{Proof of \cref{prop:recurrence}}
Our proof proceeds step-by-step, as discussed in \cref{sec:recurrence}:

\setcounter{proofstep}{0}
\begin{proofstep}{Martingale properties of $\score_{\run}$}
By \cref{asm:L2} and the fact that finiteness of second moments implies finiteness of first moments, we get $\exof{\dnorm{\sobj(\state;\sample_{\run})}} < \infty$.
We then claim that $\noise_{\run} = \nabla\obj(\act_{\run}) - \nabla\sobj(\act_{\run};\sample_{\run})$ is an $L^{2}$-bounded \acl{MDS} with respect to the natural filtration of $\sample_{\run}$.
Indeed, we have:
\begin{enumerate}
\addtolength{\itemsep}{1ex}
\item
Since $\act_{\run}$ is $\filter_{\run-1}$-measurable and $\sample_{\run}$ is \ac{iid}, we readily get
\begin{flalign}
\exof{\noise_{\run} \given \filter_{\run-1}}
	&= \exof{\nabla\obj(\act_{\run}) - \nabla\sobj(\act_{\run};\sample_{\run}) \given \filter_{\run-1}}
	\notag\\
	&= \exof{\nabla\obj(\act_{\run}) - \nabla\sobj(\act_{\run};\sample_{\run}) \given \sample_{1},\dotsc,\sample_{\run-1}}
	\notag\\
	&= \nabla\obj(\act_{\run}) - \nabla\obj(\act_{\run})
	\notag\\
	&= 0.
\end{flalign}
%so $\exof{\noise_{\run}} = \exof{\exof{\noise_{\run} \given \filter_{\run-1}}} = 0$, i.e. $\noise_{\run}$ has zero mean.

\item
Furthermore, by \cref{asm:L2}, the $L^{2}$ norm of $\noise$ satisfies
\begin{flalign}
\label{eq:vbound}
\exof{\dnorm{\noise_{\run}}^{2} \given \filter_{\run-1}}
	&= \exof{\dnorm{\nabla\obj(\act_{\run}) - \nabla\sobj(\act_{\run};\sample_{\run})}^{2} \given \filter_{\run-1}}
	\notag\\
	&\leq 2\exof{\dnorm{\nabla\obj(\act_{\run})}^{2} \given \filter_{\run-1}}
	+ 2 \exof{\dnorm{\nabla\sobj(\act_{\run};\sample_{\run})}^{2} \given \filter_{\run-1}}
	\notag\\
	&\leq 2 \dnorm{\nabla\obj(\act_{\run})}^{2}
	+ 2 \vbound^{2}
%	+ 2 \dnorm{\exof{\nabla\sobj(\act_{\run};\sample_{\run}) \given \filter_{\run-1}}}^{2}
	\notag\\
	&= 2\dnorm{\exof{\nabla\sobj(\act_{\run};\sample)}}^{2}
	+ 2\vbound^{2}
	\notag\\
	&\leq 2 \exof{\dnorm{\nabla\sobj(\act_{\run};\sample)}^{2}}
	+ 2\vbound^{2}
	\notag\\
	&\leq \noisevar,
\end{flalign}
where we set $\noisevar = 4\vbound^{2}$, and we used the dominated convergence theorem to interchange expectation and differentiation in the second line, and Jensen's inequality in the penultimate one.
%Since $\states$ is compact, there exists some finite $\bound$ such that $\dnorm{\nabla\obj(\state)} \leq \bound$ for all $\state\in\states$.
%Thus, letting $\vbound = 2\bound$, we finally obtain
%\begin{equation}
%\label{eq:vbound}
%%\exof{\dnorm{\noise_{\run}}^{2}}
%%	= \exof{\exof{\dnorm{\noise_{\run}}^{2} \given \filter_{\run-1}}}
%\exof{\dnorm{\noise_{\run}}^{2} \given \filter_{\run-1}}
%	\leq \vbound^{2}.
%\end{equation}
\end{enumerate}
\end{proofstep}

\begin{proofstep}{Recurrence of $\eps$-neighborhoods}
We proceed to show that every $\eps$-neigh\-bor\-hood $\ball(\sols,\eps)$ of $\sols$ is recurrent under $\act_{\run}$.
To do so, fix some $\eps>0$ and assume ad absurdum that $\act_{\run}$ enters $\ball(\sols,\eps)$ only a finite number of times, so there exists some finite $\run_{0}$ such that $\dist(\sols,\act_{\run}) \geq \eps$ for all $\run\geq\run_{0}$.
Since $\states\setminus\ball(\sols,\eps)$ is compact, $\payv(\state) = -\nabla \obj(\state)$ is continuous in $\state$;
furthermore, letting $\sol$ be such that $\braket{\nabla\obj(\state)}{\state - \sol} = 0$ only if $\state\in\sols$ (cf.~\cref{def:VC}),  it follows that there exists some $\const \equiv \const(\eps) > 0$ such that
\begin{equation}
\braket{\payv(\state)}{\state - \sol}
	\leq - \const
	< 0
	\quad
	\text{for all $\state\in\states\setminus\ball(\sols,\eps)$}.
\end{equation}
To proceed, let $R = \max_{\state \in \states} \norm{\state}$ and set $\beta_{\run} = \step_{\run}^{2}/(2\strong)$.
Then, letting $\fench_{\run} = \fench(\sol,\score_{\run})$ and $\snoise_{\run} = \braket{\noise_{\run}}{\act_{\run}-\sol}$, \cref{lem:Fenchel} yields
\begin{flalign}
\fench_{\run+1}
	= \fench(\sol,\score_{\run+1})
	&= \fench(\sol, \score_{\run} + \step_{\run} \est\payv_{\run})
	\notag\\
	&\leq \fench(\sol, \score_{\run})
	+ \step_{\run} \braket{\payv(\act_{\run}) + \noise_{\run}}{\act_{\run} - \sol}
	+ \beta_{\run} \dnorm{\est\payv_{\run}}^{2}
	\notag\\
	&=\fench_{\run}
	+ \step_{\run} \braket{\payv(\act_{\run})}{\act_{\run} - \sol}
	+ \step_{\run} \snoise_{\run}
	+ \beta_{\run} \dnorm{\est\payv_{\run}}^{2}
	\notag\\
	&\leq \fench_{\run}
	- \step_{\run} \const
	+ \step_{\run} \snoise_{\run}
	+ \beta_{\run} \dnorm{\est\payv_{\run}}^{2}.
\end{flalign}
Hence, letting $\tau_{\run} = \sum_{\runalt=\run_{0}}^{\run} \step_{\runalt}$ and telescoping from $\run_{0}$ to $\run$, we get
\begin{flalign}
\label{eq:bound-Fench}
\fench_{\run+1}
	&\leq \fench_{\run_{0}}
	- \const \sum_{\runalt=\run_{0}}^{\run} \step_{\runalt}
	+ \sum_{\runalt=\run_{0}}^{\run} \step_{\runalt} \snoise_{\runalt}
	+ \sum_{\runalt=\run_{0}}^{\run} \beta_{\runalt} \dnorm{\est\payv_{\runalt}}^{2}
	\notag\\
	&= \fench_{\run_{0}}
	- \tau_{\run} \bracks*{\const - \frac{\sum_{\runalt=\run_{0}}^{\run} \step_{\runalt}\snoise_{\runalt}}{\tau_{\run}}}
	+ \sum_{\runalt=\run_{0}}^{\run} \beta_{\runalt} \dnorm{\est\payv_{\runalt}}^{2}
%	\notag\\
%	&\leq \fench_{\run_{0}}
%	- \tau_{\run} \bracks*{\const - \frac{\sum_{\runalt=\run_{0}}^{\run} \step_{\runalt}\snoise_{\runalt}}{\tau_{\run}}}
%	+ 2 \smashoperator{\sum_{\runalt=\run_{0}}^{\run}} \beta_{\runalt} \bound^{2}
\end{flalign}

We now proceed to bound each term of \eqref{eq:bound-Fench}.
First, by construction, we have
\begin{equation}
\exof{\snoise_{\run} \given \filter_{\run-1}}
	= \exof{\braket{\noise_{\run}}{\act_{\run} - \sol} \given \filter_{\run-1}}
	= \braket{\exof{\noise_{\run} \given \filter_{\run-1}}}{\act_{\run} - \sol}
	= 0,
\end{equation}
where we used the fact that $\act_{\run}$ is $\filter_{\run-1}$-measurable.
Moreover, by Young's inequality, we also have
\begin{equation}
\abs{\snoise_{\run}}
	= \abs{\braket{\noise_{\run}}{\act_{\run} - \sol}}
	\leq \dnorm{\noise_{\run}} \norm{\act_{\run} - \sol}
	\leq 2R\dnorm{\noise_{\run}},
\end{equation}
where, as before, $R = \max_{\state\in\states} \norm{\state}$.
\cref{eq:vbound} then gives
\begin{equation}
\exof{\snoise_{\run}^{2} \given \filter_{\run-1}}
	\leq (2R)^{2} \exof{\dnorm{\noise_{\run}}^{2} \given \filter_{\run-1}}
	\leq 4 R^{2} \noisevar,
\end{equation}
implying in turn that $\snoise_{\run}$ is an $L^{2}$-bounded \acl{MDS}.
It then follows that $\snoise_{\run}$ satisfies the summability condition
\begin{equation}
\sum_{\run=\run_{0}}^{\infty} \frac{\exof{\abs{\step_{\run} \snoise_{\run}}^{2} \given \filter_{\run-1}}}{\tau_{\run}^{2}}
	\leq 4R^{2}\noisevar \sum_{\run=\run_{0}}^{\infty} \frac{\step_{\run}^{2}}{\tau_{\run}^{2}}
	< \infty,
\end{equation}
where the last inequality follows from the assumption that $\step_{\run}$ is square-summable.
Thus, by the \acl{LLN} for \aclp{MDS} (\cref{thm:mg_convergence1}), we get
\begin{equation}
\frac{\sum_{\runalt=\run_{0}}^{\run} \step_{\runalt} \snoise_{\runalt}}{\tau_{\run}}
	\to 0
	\quad
	\text{as $\run\to\infty$ \as},
\end{equation}
and, with $\sum_{\runalt=\run_{0}}^{\infty} \step_{\runalt} = \infty$, we finally obtain
\begin{equation}
\lim_{\run\to\infty} \tau_{\run} \bracks*{\const - \frac{\sum_{\runalt=\run_{0}}^{\run} \step_{\runalt}\snoise_{\runalt}}{\tau_{\run}}}
	= \infty
	\quad
	\as.
\end{equation}

%The third term of \eqref{eq:bound-Fench} is trivially bounded because $\step_{\run}$ is square-summable.
For the last term of \eqref{eq:bound-Fench}, let $S_{\run} = \sum_{\runalt=\run_{0}}^{\run} \beta_{\runalt} \dnorm{\est\payv_{\runalt}}^{2}$, so $S_{\run}$ is $\filter_{\run}$-measurable and nondecrasing.
In addition, we have
\begin{equation}
\exof{S_{\run}}
	= \sum_{\runalt=\run_{0}}^{\run} \beta_{\runalt} \exof{\dnorm{\est\payv_{\runalt}}^{2}}
	\leq \vbound^{2} \sum_{\runalt=\run_{0}}^{\run} \beta_{\runalt}
	< \infty,
\end{equation}
with the last step following from \eqref{eq:vbound}.
This implies that $S_{\run}$ is an $L^{1}$-bounded submartingale so, by Doob's submartingale convergence theorem (\cref{thm:mg_convergence2}), $S_{\run}$ converges almost surely to some random variable $S_{\infty}$, \ie the last term of \eqref{eq:bound-Fench} is bounded.
Hence, combining all of the above, we finally obtain
\begin{equation}
\limsup_{\run\to\infty} \fench_{\run}
	= - \infty
	\quad
	\as,
\end{equation}
contradicting the positive-definiteness of the Fenchel coupling (cf.~\cref{lem:Fenchel}).
We thus conclude that $\act_{\run}$ enters $\ball(\sols,\eps)$ infinitely many times \as, as claimed.
\end{proofstep}

\begin{proofstep}{Recurrence of Fenchel zones}
Using the reciprocity of the Fenchel coupling (\cref{asm:reciprocity}), we show below that every Fenchel zone $\fball(\sols,\delta)$ of $\sols$ contains an $\eps$-neighborhood of $\sols$.
%\begin{equation}\label{eq:contains}
%\forall \delta > 0,\exists \eps(\delta) > 0, \ball(\sols,\eps) \subset \fball(\sols, \delta).
%\end{equation} 
Then, given that $\act_{\run}$ enters $\ball(\sols,\eps)$ infinitely often (per the previous step), it will also enter $\fball(\sols, \delta)$ infinitely often.

To establish this claim, assume instead that there is no $\eps$-ball $\ball(\sols,\eps)$ contained in $\fball(\sols, \delta)$.
Then, for all $\runalt>0$ there exists some $\dstate_{\runalt}\in\dstates$ such that $\dist(\sols,\mirror(\dstate_{\runalt})) = 1/\runalt$ but $\fench(\sols, y_{\delta}) \geq \eps$.
This produces a sequence $(\dstate_{\runalt})_{\runalt=1}^{\infty}$ such that $\dist(\sols,\mirror(\dstate_{\runalt})) \to 0$ but $\fench(\sols, \dstate_{\runalt}) \geq \eps$.
Since $\states$ is compact and $\sols$ is closed, we can assume without loss of generality that $\mirror(\dstate_{\runalt})\to\base$ for some $\base\in\sols$ (at worst, we only need to descend to a subsequence of $\dstate_{\runalt}$).
We thus get
\begin{equation}
\eps
	\leq \fench(\sols,\dstate_{\runalt})
	\leq \fench(\base,\dstate_{\runalt}).
\end{equation}
However, since $\mirror(\dstate_{\runalt})\to\base$, \cref{asm:reciprocity} gives $\fench(\base,\dstate_{\runalt})\to0$, a contradiction.
We conclude that $\fball(\sols,\delta)$ contains an $\eps$-neighborhood of $\sols$, as required.
\end{proofstep}
\end{proofof}

\begin{proof}[Proof of \cref{thm:global}]
Let $\sol\in\sols$ be a minimum point of \eqref{eq:opt}.
Then, letting $\fench_{\run} = \fench(\sol,\score_{\run})$, \cref{lem:Fenchel} gives
\begin{flalign}
\label{eq:Fench-bound1}
\fench_{\run+1}
	= \fench(\sol,\score_{\run+1})
	&= \fench(\sol,\score_{\run} + \step_{\run}\est\payv_{\run})
	\notag\\
	&\leq \fench(\sol,\score_{\run})
	+ \step_{\run} \braket{\est\payv_{\run}}{\act_{\run} - \sol}
	+ \frac{\step_{\run}^{2}}{2\strong} \dnorm{\est\payv_{\run}}^{2}
	\notag\\
	&= \fench_{\run}
	+ \step_{\run} \braket{\payv(\act_{\run})}{\act_{\run} - \sol}
	+ \step_{\run} \snoise_{\run}
%	+ \step_{\run} \braket{\noise_{\run}}{\act_{\run} - \sol}
	+ \frac{\step_{\run}^{2}}{2\strong} \dnorm{\est\payv_{\run}}^{2}
	\notag\\
	&\leq \fench_{\run}
	+ \step_{\run} \snoise_{\run}
	+ \frac{\step_{\run}^{2}}{2\strong} \dnorm{\est\payv_{\run}}^{2},
\end{flalign}
where we set $\snoise_{\run} = \braket{\noise_{\run}}{\act_{\run} - \sol}$ in the third line and used the fact that $\obj$ satisfies \eqref{eq:VC} in the last one.

Since $\score_{\run}$ is predictable relative to $\filter_{\run}$ (\ie $\score_{\run}$ is $\filter_{\run-1}$-measurable), the process $\fench_{\run} = \fench(\sol,\score_{\run})$ is itself adapted to the shifted filtration $\alt\filter_{\run} = \sigma(\sample_{\start},\score_{2}\dotsc,\sample_{\run-1},\score_{\run}) = \filter_{\run-1}$.
Thus, taking conditional expectations and invoking \cref{asm:L2}, the bound \eqref{eq:Fench-bound1} becomes:
\begin{flalign}
\label{eq:Fench-bound-cond}
\exof{\fench_{\run+1} \given \alt\filter_{\run}}
	&\leq \fench_{\run}
	+ \exof{\snoise_{\run} \given \alt\filter_{\run}}
	+ \frac{\step_{\run}^{2}}{2\strong} \exof{\dnorm{\est\payv_{\run}}^{2} \given \alt\filter_{\run}}
	\notag\\
	&= \fench_{\run}
	+ \exof{\snoise_{\run} \given \filter_{\run-1}}
	+ \frac{\step_{\run}^{2}}{2\strong} \exof{\dnorm{\nabla\sobj(\act_{\run};\sample_{\run})}^{2} \given \filter_{\run-1}}
	\notag\\
	&\leq \fench_{\run}
	+ \frac{\step_{\run}^{2} \vbound^{2}}{2\strong},
\end{flalign}
where, in the last line, we used \cref{asm:L2} and the fact that $\noise_{\run}$ is a \acl{MDS} (so $\exof{\snoise_{\run} \given \filter_{\run-1}} = 0$; for a detailed derivation, see the proof of \cref{prop:recurrence} in \cref{app:proofs}).
Hence, with $\sum_{\run=\start}^{\infty} \step_{\run}^{2} < \infty$, \cref{lem:Gladyshev} implies that $\fench_{\run}$ converges \as to some finite limit $\fench_{\infty}$.

\begin{proofstep}{Martingale properties of $\score_{\run}$}
First, let
\begin{equation}
\payv(\state)
	= - \exof{\nabla\sobj(\state;\sample)} = -\nabla\obj(\state)
\end{equation}
denote the negative gradient of $\obj$ at $\state\in\states$, and write
\begin{equation}
\label{eq:oracle}
\est\payv_{\run}
	= -\nabla\sobj(\act_{\run};\sample_{\run})
\end{equation}
for the corresponding oracle feedback at stage $\run$.
Then, \cref{alg:SMD} may be written in Robbins\textendash Monro form as
\begin{equation}
\label{eq:SA}
\score_{\run+1}
	= \score_{\run} + \step_{\run} \est\payv_{\run}
	= \score_{\run} + \step_{\run} \bracks{\payv(\act_{\run}) + \noise_{\run}},
\end{equation}
where
\begin{equation}
\noise_{\run}
	= \nabla\obj(\act_{\run}) - \nabla\sobj(\act_{\run};\sample_{\run})
\end{equation}
denotes the difference between the mean gradient of $\obj$ at $\act_{\run}$ and the $\run$-th stage gradient sample.%
\footnote{Recall here that there is a one-step offset between $\act_{\run}$ and $\sample_{\run+1}$ at the $\run$-th iteration of \ac{SMD}.}

\begin{subequations}
\label{eq:MDS}
By construction, $\noise_{\run}$ is a \acl{MDS} relative to the history (natural filtration) $\filter_{\run} = \sigma(\sample_{1},\dotsc,\sample_{\run})$ of $\sample_{\run}$, \ie
\begin{equation}
\label{eq:zero-mean}
\exof{\noise_{\run}\given\filter_{\run-1}}
	= 0
	\quad
	\text{for all $\run$.}
\end{equation}
Furthermore, by \cref{asm:L2}, it readily follows that $\noise_{\run}$ has uniformly bounded second moments, \ie there exists some finite $\noisedev\geq0$ such that
\begin{equation}
\label{eq:MSE}
\exof{\dnorm{\noise_{\run}}^{2} \given \filter_{\run-1}}
	\leq \noisevar
	\quad
	\text{for all $\run$},
\end{equation}
implying in turn that $\noise_{\run}$ is bounded in $L^{2}$ (for a more detailed treatment, see \cref{app:proofs}).
\end{subequations}
\end{proofstep}

\begin{proofstep}{Recurrence of $\eps$-neighborhoods}
Invoking the \acl{LLN} for $L^{2}$-bounded \aclp{MDS} and using the Fenchel coupling as an energy function (cf.~\cref{app:proofs}), we show that if $\act_{\run}$ remains outside $\ball(\sols,\eps)$ for sufficiently large $\run$, we must also have $\fench(\sols,\score_{\run})\to-\infty$ \as.
This contradicts the positive-definiteness of $\fench$, so $\act_{\run}$ must enter $\ball(\sols,\eps)$ infinitely often \as.
\end{proofstep}

\begin{proofstep}{Recurrence of Fenchel zones}
By reciprocity (\cref{asm:reciprocity}), $\fball(\sols, \delta)$ always contains an $\eps$-neighborhood of $\sols$.
%within it: $\forall \delta > 0$, $\exists \eps(\delta) > 0$ such that: $\ball(\sols,\eps) \subset \fball(\sols, \delta)$.
Since $\act_{\run}$ enters $\ball(\sols,\eps)$ infinitely many times \as, the same must hold for $\fball(\sols, \delta)$.
Our claim and \cref{cor:recurrence} then follow immediately.
\end{proofstep}

\begin{proofof}{Proof of \cref{lem:Fenchel}}
To prove the first claim, let $\state =\mirror(\dstate) = \argmax_{\alt\state\in\states}\{\braket{\dstate}{\alt\state} - \hreg(\alt\state)\}$, so $\dstate\in\pd \hreg(\state)$ from standard results in convex analysis \cite{Roc70}.
%($y$ is a subgradient of $\hreg(p)$ if and only if $p=\mirror(\dstate)$).
We thus get:
\begin{equation}
\label{eq:Fench-sub}
\fench(\base,\dstate) = \hreg(\base) + \hreg^{\ast}(\dstate) - \braket{\dstate}{\base}
%	= \hreg(\base) + \braket{\dstate}{\mirror(\dstate)} - \hreg(\mirror(\dstate)) - \braket{\dstate}{\base}
	= \hreg(\base) - \hreg(\state) - \braket{\dstate}{\base - \state}.
\end{equation}
Since $\dstate \in \pd \hreg(\state)$ and $\hreg$ is $\strong$-strongly convex, we also have
\begin{equation}
\hreg(\state) + \tau\braket{\dstate}{\base - \state}
	\leq \hreg(\state + \tau(\base - \state))
	\leq (1-\tau) \hreg(\state) + \tau \hreg(\base) - \tfrac{1}{2} \strong \tau(1-\tau) \norm{\state - \base}^{2}
\end{equation}
for all $\tau\in[0,1]$, thereby leading to the bound
\begin{equation}
\label{eq:divbound}
\tfrac{1}{2} \strong(1-\tau) \norm{\state - \base}^{2}
	\leq \hreg(\base) - \hreg(\state) - \braket{\dstate}{\base - \state}
	= \fench(\base,\dstate).
\end{equation}
Our claim then follows by letting $\tau\to0^{+}$ in \eqref{eq:divbound}.

For our second claim, we start by citing a well-known duality principle for strongly convex functions \cite[Theorem 12.60]{RW98}:
If $f\from\R^{\vdim}\to\R\cup\{-\infty,+\infty\}$ is proper, lower semi-continuous and convex, its convex conjugate $f^{\ast}$ is $\sigma$-strongly convex if and only if $f$ is differentiable and satisfies
\begin{equation}
f(\alt\state)
	\leq f(\state) + \braket{\nabla f(\state)}{\alt\state - \state} + \frac{1}{2\sigma} \norm{\alt\state - \state}^{2}
\end{equation}
for all $\state,\alt\state\in\R^{\vdim}$.
In our case, if we extend $\hreg$ to all of $\vecspace$ by setting $\hreg\equiv+\infty$ outside $\states$, we have that $\hreg$ is $\strong$-strongly convex, lower semi-continuous and proper, so $(\hreg^{\ast})^{\ast} = \hreg$ \cite[Theorem 11.1]{RW98}.
It is also easy to see that $\hreg^{\ast}$ is proper, lower semi-continuous and convex (since it is a point-wise maximum of affine functions by definition), so the $\strong$-strong convexity of $\hreg = (\hreg^{\ast})^{\ast}$ implies that $\hreg^{\ast}$ is differentiable and satisfies
\begin{flalign}
\label{eq:smoothness}
\hreg^{\ast}(\alt\dstate)
	&\leq \hreg^{\ast}(\dstate)
	+ \braket{\alt\dstate - \dstate}{\nabla \hreg^{\ast}(\dstate)}
	+ \frac{1}{2\strong} \dnorm{\alt\dstate - \dstate}^{2}
	\\
	&= \hreg^{\ast}(\dstate)
	+ \braket{\alt\dstate - \dstate}{\mirror(\dstate)} +
	\frac{1}{2\strong} \dnorm{\alt\dstate - \dstate}^{2}
\end{flalign}
for all $\dstate,\alt\dstate\in\dstates$, where the last equality follows from the fact that $\nabla \hreg^{\ast}(\dstate) = \mirror(\dstate)$.

Therefore, substituting the preceding inequality in the definition of the Fenchel coupling, we obtain
\begin{flalign}
\fench(\state,\alt\dstate)
	&= \hreg(\state) + \hreg^{\ast}(\alt\dstate) - \braket{\alt\dstate}{\state}
	\notag\\
	&\leq \hreg(\state) + \hreg^{\ast}(\dstate) + \braket{\alt\dstate - \dstate}{\nabla \hreg^{\ast}(\dstate)} + \frac{1}{2\strong} \dnorm{\alt\dstate - \dstate}^{2} - \braket{\alt\dstate}{\state}
	\notag\\
	&= \fench(\state,\dstate) + \braket{\alt\dstate - \dstate}{\mirror(\dstate) - \state} + \frac{1}{2\strong} \dnorm{\alt\dstate - \dstate}^{2},
\end{flalign}
and our assertion follows.
\end{proofof}

\begin{proofof}{Proof of \cref{prop:recurrence}}
Our proof proceeds step-by-step, as discussed in \cref{sec:recurrence}:

\setcounter{proofstep}{0}
\begin{proofstep}{Martingale properties of $\score_{\run}$}
By \cref{asm:L2} and the fact that finiteness of second moments implies finiteness of first moments, we get $\exof{\dnorm{\sobj(\state;\sample_{\run})}} < \infty$.
We then claim that $\noise_{\run} = \nabla\obj(\act_{\run}) - \nabla\sobj(\act_{\run};\sample_{\run})$ is an $L^{2}$-bounded \acl{MDS} with respect to the natural filtration of $\sample_{\run}$.
Indeed, we have:
\begin{enumerate}
\addtolength{\itemsep}{1ex}
\item
Since $\act_{\run}$ is $\filter_{\run-1}$-measurable and $\sample_{\run}$ is \ac{iid}, we readily get
\begin{flalign}
\exof{\noise_{\run} \given \filter_{\run-1}}
	&= \exof{\nabla\obj(\act_{\run}) - \nabla\sobj(\act_{\run};\sample_{\run}) \given \filter_{\run-1}}
	\notag\\
	&= \exof{\nabla\obj(\act_{\run}) - \nabla\sobj(\act_{\run};\sample_{\run}) \given \sample_{1},\dotsc,\sample_{\run-1}}
	\notag\\
	&= \nabla\obj(\act_{\run}) - \nabla\obj(\act_{\run})
	\notag\\
	&= 0.
\end{flalign}
%so $\exof{\noise_{\run}} = \exof{\exof{\noise_{\run} \given \filter_{\run-1}}} = 0$, i.e. $\noise_{\run}$ has zero mean.

\item
Furthermore, by \cref{asm:L2}, the $L^{2}$ norm of $\noise$ satisfies
\begin{flalign}
\label{eq:vbound}
\exof{\dnorm{\noise_{\run}}^{2} \given \filter_{\run-1}}
	&= \exof{\dnorm{\nabla\obj(\act_{\run}) - \nabla\sobj(\act_{\run};\sample_{\run})}^{2} \given \filter_{\run-1}}
	\notag\\
	&\leq 2\exof{\dnorm{\nabla\obj(\act_{\run})}^{2} \given \filter_{\run-1}}
	+ 2 \exof{\dnorm{\nabla\sobj(\act_{\run};\sample_{\run})}^{2} \given \filter_{\run-1}}
	\notag\\
	&\leq 2 \dnorm{\nabla\obj(\act_{\run})}^{2}
	+ 2 \vbound^{2}
%	+ 2 \dnorm{\exof{\nabla\sobj(\act_{\run};\sample_{\run}) \given \filter_{\run-1}}}^{2}
	\notag\\
	&= 2\dnorm{\exof{\nabla\sobj(\act_{\run};\sample)}}^{2}
	+ 2\vbound^{2}
	\notag\\
	&\leq 2 \exof{\dnorm{\nabla\sobj(\act_{\run};\sample)}^{2}}
	+ 2\vbound^{2}
	\notag\\
	&\leq \noisevar,
\end{flalign}
where we set $\noisevar = 4\vbound^{2}$, and we used the dominated convergence theorem to interchange expectation and differentiation in the second line, and Jensen's inequality in the penultimate one.
%Since $\states$ is compact, there exists some finite $\bound$ such that $\dnorm{\nabla\obj(\state)} \leq \bound$ for all $\state\in\states$.
%Thus, letting $\vbound = 2\bound$, we finally obtain
%\begin{equation}
%\label{eq:vbound}
%%\exof{\dnorm{\noise_{\run}}^{2}}
%%	= \exof{\exof{\dnorm{\noise_{\run}}^{2} \given \filter_{\run-1}}}
%\exof{\dnorm{\noise_{\run}}^{2} \given \filter_{\run-1}}
%	\leq \vbound^{2}.
%\end{equation}
\end{enumerate}
\end{proofstep}

\begin{proofstep}{Recurrence of $\eps$-neighborhoods}
We proceed to show that every $\eps$-neigh\-bor\-hood $\ball(\sols,\eps)$ of $\sols$ is recurrent under $\act_{\run}$.
To do so, fix some $\eps>0$ and assume ad absurdum that $\act_{\run}$ enters $\ball(\sols,\eps)$ only a finite number of times, so there exists some finite $\run_{0}$ such that $\dist(\sols,\act_{\run}) \geq \eps$ for all $\run\geq\run_{0}$.
Since $\states\setminus\ball(\sols,\eps)$ is compact, $\payv(\state) = -\nabla \obj(\state)$ is continuous in $\state$;
furthermore, letting $\sol$ be such that $\braket{\nabla\obj(\state)}{\state - \sol} = 0$ only if $\state\in\sols$ (cf.~\cref{def:VC}),  it follows that there exists some $\const \equiv \const(\eps) > 0$ such that
\begin{equation}
\braket{\payv(\state)}{\state - \sol}
	\leq - \const
	< 0
	\quad
	\text{for all $\state\in\states\setminus\ball(\sols,\eps)$}.
\end{equation}

To proceed, let $R = \max_{\state \in \states} \norm{\state}$ and set $\beta_{\run} = \step_{\run}^{2}/(2\strong)$.
Then, letting $\fench_{\run} = \fench(\sol,\score_{\run})$ and $\snoise_{\run} = \braket{\noise_{\run}}{\act_{\run}-\sol}$, \cref{lem:Fenchel} yields
\begin{flalign}
\fench_{\run+1}
	= \fench(\sol,\score_{\run+1})
	&= \fench(\sol, \score_{\run} + \step_{\run} \est\payv_{\run})
	\notag\\
	&\leq \fench(\sol, \score_{\run})
	+ \step_{\run} \braket{\payv(\act_{\run}) + \noise_{\run}}{\act_{\run} - \sol}
	+ \beta_{\run} \dnorm{\est\payv_{\run}}^{2}
	\notag\\
	&=\fench_{\run}
	+ \step_{\run} \braket{\payv(\act_{\run})}{\act_{\run} - \sol}
	+ \step_{\run} \snoise_{\run}
	+ \beta_{\run} \dnorm{\est\payv_{\run}}^{2}
	\notag\\
	&\leq \fench_{\run}
	- \step_{\run} \const
	+ \step_{\run} \snoise_{\run}
	+ \beta_{\run} \dnorm{\est\payv_{\run}}^{2}.
\end{flalign}
Hence, letting $\tau_{\run} = \sum_{\runalt=\run_{0}}^{\run} \step_{\runalt}$ and telescoping from $\run_{0}$ to $\run$, we get
\begin{flalign}
\label{eq:bound-Fench}
\fench_{\run+1}
	&\leq \fench_{\run_{0}}
	- \const \sum_{\runalt=\run_{0}}^{\run} \step_{\runalt}
	+ \sum_{\runalt=\run_{0}}^{\run} \step_{\runalt} \snoise_{\runalt}
	+ \sum_{\runalt=\run_{0}}^{\run} \beta_{\runalt} \dnorm{\est\payv_{\runalt}}^{2}
	\notag\\
	&= \fench_{\run_{0}}
	- \tau_{\run} \bracks*{\const - \frac{\sum_{\runalt=\run_{0}}^{\run} \step_{\runalt}\snoise_{\runalt}}{\tau_{\run}}}
	+ \sum_{\runalt=\run_{0}}^{\run} \beta_{\runalt} \dnorm{\est\payv_{\runalt}}^{2}
%	\notag\\
%	&\leq \fench_{\run_{0}}
%	- \tau_{\run} \bracks*{\const - \frac{\sum_{\runalt=\run_{0}}^{\run} \step_{\runalt}\snoise_{\runalt}}{\tau_{\run}}}
%	+ 2 \smashoperator{\sum_{\runalt=\run_{0}}^{\run}} \beta_{\runalt} \bound^{2}
\end{flalign}

We now proceed to bound each term of \eqref{eq:bound-Fench}.
First, by construction, we have
\begin{equation}
\exof{\snoise_{\run} \given \filter_{\run-1}}
	= \exof{\braket{\noise_{\run}}{\act_{\run} - \sol} \given \filter_{\run-1}}
	= \braket{\exof{\noise_{\run} \given \filter_{\run-1}}}{\act_{\run} - \sol}
	= 0,
\end{equation}
where we used the fact that $\act_{\run}$ is $\filter_{\run-1}$-measurable.

Moreover, by Young's inequality, we also have
\begin{equation}
\abs{\snoise_{\run}}
	= \abs{\braket{\noise_{\run}}{\act_{\run} - \sol}}
	\leq \dnorm{\noise_{\run}} \norm{\act_{\run} - \sol}
	\leq 2R\dnorm{\noise_{\run}},
\end{equation}
where, as before, $R = \max_{\state\in\states} \norm{\state}$.
\cref{eq:vbound} then gives
\begin{equation}
\exof{\snoise_{\run}^{2} \given \filter_{\run-1}}
	\leq (2R)^{2} \exof{\dnorm{\noise_{\run}}^{2} \given \filter_{\run-1}}
	\leq 4 R^{2} \noisevar,
\end{equation}
implying in turn that $\snoise_{\run}$ is an $L^{2}$-bounded \acl{MDS}.

It then follows that $\snoise_{\run}$ satisfies the summability condition
\begin{equation}
\sum_{\run=\run_{0}}^{\infty} \frac{\exof{\abs{\step_{\run} \snoise_{\run}}^{2} \given \filter_{\run-1}}}{\tau_{\run}^{2}}
	\leq 4R^{2}\noisevar \sum_{\run=\run_{0}}^{\infty} \frac{\step_{\run}^{2}}{\tau_{\run}^{2}}
	< \infty,
\end{equation}
where the last inequality follows from the assumption that $\step_{\run}$ is square-summable.
Thus, by the \acl{LLN} for \aclp{MDS} (\cref{thm:mg_convergence1}), we get
\begin{equation}
\frac{\sum_{\runalt=\run_{0}}^{\run} \step_{\runalt} \snoise_{\runalt}}{\tau_{\run}}
	\to 0
	\quad
	\text{as $\run\to\infty$ \as},
\end{equation}
and, with $\sum_{\runalt=\run_{0}}^{\infty} \step_{\runalt} = \infty$, we finally obtain
\begin{equation}
\lim_{\run\to\infty} \tau_{\run} \bracks*{\const - \frac{\sum_{\runalt=\run_{0}}^{\run} \step_{\runalt}\snoise_{\runalt}}{\tau_{\run}}}
	= \infty
	\quad
	\as.
\end{equation}

For the last term of \eqref{eq:bound-Fench}, let $S_{\run} = \sum_{\runalt=\run_{0}}^{\run} \beta_{\runalt} \dnorm{\est\payv_{\runalt}}^{2}$, so $S_{\run}$ is $\filter_{\run}$-measurable and nondecrasing.
In addition, we have
\begin{equation}
\exof{S_{\run}}
	= \sum_{\runalt=\run_{0}}^{\run} \beta_{\runalt} \exof{\dnorm{\est\payv_{\runalt}}^{2}}
	\leq \vbound^{2} \sum_{\runalt=\run_{0}}^{\run} \beta_{\runalt}
	< \infty,
\end{equation}
with the last step following from \eqref{eq:vbound}.
This implies that $S_{\run}$ is an $L^{1}$-bounded submartingale so, by Doob's submartingale convergence theorem (\cref{thm:mg_convergence2}), $S_{\run}$ converges almost surely to some random variable $S_{\infty}$, \ie the last term of \eqref{eq:bound-Fench} is bounded.

Hence, combining all of the above, we finally obtain
\begin{equation}
\limsup_{\run\to\infty} \fench_{\run}
	= - \infty
	\quad
	\as,
\end{equation}
contradicting the positive-definiteness of the Fenchel coupling (cf.~\cref{lem:Fenchel}).
We thus conclude that $\act_{\run}$ enters $\ball(\sols,\eps)$ infinitely many times \as, as claimed.
\end{proofstep}

\begin{proofstep}{Recurrence of Fenchel zones}
Using the reciprocity of the Fenchel coupling (\cref{asm:reciprocity}), we show below that every Fenchel zone $\fball(\sols,\delta)$ of $\sols$ contains an $\eps$-neighborhood of $\sols$.
%\begin{equation}\label{eq:contains}
%\forall \delta > 0,\exists \eps(\delta) > 0, \ball(\sols,\eps) \subset \fball(\sols, \delta).
%\end{equation} 
Then, given that $\act_{\run}$ enters $\ball(\sols,\eps)$ infinitely often (per the previous step), it will also enter $\fball(\sols, \delta)$ infinitely often.
